
const WORDS=[{"id": 0, "w": "门槛", "p": "ménkǎn", "t": "名词", "m": "ngưỡng cửa; ngưỡng, điều kiện để bắt đầu hoặc tham gia", "coll": "跨过门槛、入学门槛", "s": "这项工作的入职门槛并不高，但需要认真负责。"}, {"id": 1, "w": "报社", "p": "bàoshè", "t": "名词", "m": "tòa soạn báo", "coll": "在报社工作、报社编辑", "s": "大学毕业以后，她进入一家报社担任记者。"}, {"id": 2, "w": "编辑", "p": "biānjí", "t": "名词 / 动词", "m": "biên tập viên; biên tập", "coll": "编辑文章、报社编辑", "s": "这位编辑正在认真检查准备发表的文章。"}, {"id": 3, "w": "嗯", "p": "ǹg", "t": "叹词", "m": "ừ, vâng (đáp lời, đồng ý)", "coll": "嗯，好的、嗯，我明白了", "s": "“嗯，我明白你的意思了，我们再商量一下。”"}, {"id": 4, "w": "轻易", "p": "qīngyì", "t": "形容词 / 副词", "m": "dễ dàng; tùy tiện, khinh suất", "coll": "轻易得到、不轻易放弃", "s": "面对一次失败，我们不应该轻易放弃自己的目标。"}, {"id": 5, "w": "处理", "p": "chǔlǐ", "t": "动词", "m": "xử lý, giải quyết", "coll": "处理问题、处理文件", "s": "收到顾客的意见以后，经理立即安排人员处理这个问题。"}, {"id": 6, "w": "社区", "p": "shèqū", "t": "名词", "m": "cộng đồng dân cư, khu dân cư", "coll": "社区居民、社区活动", "s": "这个社区每个月都会组织适合老年人参加的活动。"}, {"id": 7, "w": "劝", "p": "quàn", "t": "动词", "m": "khuyên, thuyết phục", "coll": "劝他休息、劝人戒烟", "s": "看到他连续工作了很久，同事们都劝他先休息一会儿。"}, {"id": 8, "w": "圆", "p": "yuán", "t": "形容词", "m": "tròn", "coll": "圆桌、圆形标志", "s": "这张圆桌放在客厅中间，可以坐下六个人。"}, {"id": 9, "w": "标志", "p": "biāozhì", "t": "名词", "m": "biển báo; dấu hiệu, biểu tượng", "coll": "交通标志、安全标志", "s": "开车经过学校附近时，司机应该特别注意路边的交通标志。"}, {"id": 10, "w": "出示", "p": "chūshì", "t": "动词", "m": "xuất trình, đưa ra cho xem", "coll": "出示证件、出示文件", "s": "进入展览馆以前，请向工作人员出示您的有效证件。"}, {"id": 11, "w": "赞成", "p": "zànchéng", "t": "动词", "m": "tán thành, đồng tình", "coll": "赞成提议、表示赞成", "s": "经过充分讨论，大多数居民都赞成这个计划。"}, {"id": 12, "w": "请愿书", "p": "qǐngyuànshū", "t": "名词", "m": "đơn kiến nghị, bản thỉnh nguyện", "coll": "一份请愿书、在请愿书上签名", "s": "为了保护附近的公园，居民们共同提交了一份请愿书。"}, {"id": 13, "w": "恋爱", "p": "liàn'ài", "t": "名词 / 动词", "m": "yêu đương; tình yêu đôi lứa", "coll": "谈恋爱、恋爱关系", "s": "他们在大学里认识，毕业以后才开始谈恋爱。"}, {"id": 14, "w": "迫切", "p": "pòqiè", "t": "形容词", "m": "cấp thiết, bức thiết", "coll": "迫切需要、迫切的愿望", "s": "随着居民不断增加，这个社区迫切需要一所新的学校。"}, {"id": 15, "w": "犹豫", "p": "yóuyù", "t": "动词", "m": "do dự, lưỡng lự", "coll": "犹豫不决、毫不犹豫", "s": "面对这两个不同的选择，她犹豫了很久，还是没有作出决定。"}, {"id": 16, "w": "冷淡", "p": "lěngdàn", "t": "形容词", "m": "lạnh nhạt, hờ hững", "coll": "态度冷淡、反应冷淡", "s": "他对陌生人的态度有些冷淡，但对朋友十分热情。"}, {"id": 17, "w": "无所谓", "p": "wúsuǒwèi", "t": "动词", "m": "không quan trọng, thế nào cũng được; không để tâm", "coll": "都无所谓、无所谓输赢", "s": "对我来说，坐在哪个位置都无所谓，只要能听清楚就行。"}, {"id": 18, "w": "值班", "p": "zhí bān", "t": "动词", "m": "trực, làm nhiệm vụ theo ca", "coll": "周末值班、轮流值班", "s": "为了保证游客的安全，工作人员会在节假日轮流值班。"}, {"id": 19, "w": "报告", "p": "bàogào", "t": "名词 / 动词", "m": "báo cáo; bản báo cáo", "coll": "工作报告、写报告", "s": "会议开始以前，她已经准备好了这份工作报告。"}, {"id": 20, "w": "八成", "p": "bāchéng", "t": "副词", "m": "có lẽ, rất có thể, phần nhiều là", "coll": "八成是忘了、八成来不及", "s": "他平时总是准时到，今天这么晚还没来，八成是路上堵车了。"}, {"id": 21, "w": "模糊", "p": "móhu", "t": "形容词 / 动词", "m": "mờ, không rõ; làm mờ, làm không rõ", "coll": "视线模糊、记忆模糊", "s": "时间过去太久，他对那件事的记忆已经有些模糊了。"}, {"id": 22, "w": "狡猾", "p": "jiǎohuá", "t": "形容词", "m": "xảo quyệt, ranh mãnh", "coll": "狡猾的狐狸、十分狡猾", "s": "故事里的狐狸十分狡猾，总是想办法欺骗其他动物。"}, {"id": 23, "w": "了不起", "p": "liǎobuqǐ", "t": "形容词", "m": "giỏi giang, xuất sắc, đáng nể", "coll": "了不起的成就、真了不起", "s": "他靠自己的努力完成了这项艰巨的任务，真了不起。"}, {"id": 24, "w": "身段", "p": "shēnduàn", "t": "名词", "m": "dáng người, tư thế; thái độ, tư thế khi đối nhân xử thế", "coll": "放低身段、身段优美", "s": "即使经验丰富，他也愿意放低身段，向年轻同事请教。"}, {"id": 25, "w": "缩短", "p": "suōduǎn", "t": "动词", "m": "rút ngắn", "coll": "缩短时间、缩短距离", "s": "这条新公路大大缩短了两个城市之间的距离。"}, {"id": 26, "w": "看不起", "p": "kànbuqǐ", "t": "动词短语", "m": "coi thường, khinh thường", "coll": "看不起别人、被人看不起", "s": "我们不应该因为一个人的工作普通，就看不起他。"}, {"id": 27, "w": "谦虚", "p": "qiānxū", "t": "形容词", "m": "khiêm tốn", "coll": "谦虚好学、为人谦虚", "s": "虽然取得了很好的成绩，她仍然保持谦虚好学的态度。"}, {"id": 28, "w": "实践", "p": "shíjiàn", "t": "动词 / 名词", "m": "thực hành, thực tiễn; đưa vào thực hiện", "coll": "社会实践、付诸实践", "s": "学到了新的方法以后，我们还应该把它们付诸实践。"}];
const CHUNKS={"0": ["这项工作的入职门槛", "并不高，", "但需要认真负责。"], "1": ["大学毕业以后，", "她进入一家报社", "担任记者。"], "2": ["这位编辑", "正在认真检查", "准备发表的文章。"], "3": ["“嗯，", "我明白你的意思了，", "我们再商量一下。”"], "4": ["面对一次失败，", "我们不应该", "轻易放弃自己的目标。"], "5": ["收到顾客的意见以后，", "经理立即安排人员", "处理这个问题。"], "6": ["这个社区", "每个月都会组织", "适合老年人参加的活动。"], "7": ["看到他连续工作了很久，", "同事们都劝他", "先休息一会儿。"], "8": ["这张圆桌", "放在客厅中间，", "可以坐下六个人。"], "9": ["开车经过学校附近时，", "司机应该特别注意", "路边的交通标志。"], "10": ["进入展览馆以前，", "请向工作人员", "出示您的有效证件。"], "11": ["经过充分讨论，", "大多数居民", "都赞成这个计划。"], "12": ["为了保护附近的公园，", "居民们共同提交了", "一份请愿书。"], "13": ["他们在大学里认识，", "毕业以后", "才开始谈恋爱。"], "14": ["随着居民不断增加，", "这个社区", "迫切需要一所新的学校。"], "15": ["面对这两个不同的选择，", "她犹豫了很久，", "还是没有作出决定。"], "16": ["他对陌生人的态度", "有些冷淡，", "但对朋友十分热情。"], "17": ["对我来说，", "坐在哪个位置都无所谓，", "只要能听清楚就行。"], "18": ["为了保证游客的安全，", "工作人员", "会在节假日轮流值班。"], "19": ["会议开始以前，", "她已经准备好了", "这份工作报告。"], "20": ["他平时总是准时到，", "今天这么晚还没来，", "八成是路上堵车了。"], "21": ["时间过去太久，", "他对那件事的记忆", "已经有些模糊了。"], "22": ["故事里的狐狸十分狡猾，", "总是想办法", "欺骗其他动物。"], "23": ["他靠自己的努力", "完成了这项艰巨的任务，", "真了不起。"], "24": ["即使经验丰富，", "他也愿意放低身段，", "向年轻同事请教。"], "25": ["这条新公路", "大大缩短了", "两个城市之间的距离。"], "26": ["我们不应该因为", "一个人的工作普通，", "就看不起他。"], "27": ["虽然取得了很好的成绩，", "她仍然保持", "谦虚好学的态度。"], "28": ["学到了新的方法以后，", "我们还应该", "把它们付诸实践。"]};
'use strict';
const root=document.getElementById('ntc-design-preview');
const $=id=>document.getElementById(id);
const STORE='ngocthucac-hsk5-bai31-learning-v3';
const pages=['词汇表','学习生词','词汇卡片','综合练习','连词成句','学习统计'];
let storageOK=true,store={active:null,profiles:{}};
try{let raw=localStorage.getItem(STORE);if(raw){let parsed=JSON.parse(raw);if(parsed&&parsed.profiles)store=parsed}}catch(e){storageOK=false}
let student=store.active?store.profiles[store.active]:null;
if(!student){store.active='local';student=store.profiles.local||createStudent('','');store.profiles.local=student;}
let ui=student?.ui||{page:0,g:0,idx:0,pinyin:false};
let speed=1,playback=null,audioGeneration=0;
const group=g=>WORDS.slice(g*10,g===2?WORDS.length:g*10+10);
const groupOf=id=>Math.min(2,Math.floor(id/10));
const escapeHTML=t=>String(t).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const hasLearned=id=>!!student?.studied.includes(id);
const learned=g=>group(g).filter(d=>hasLearned(d.id)).length;
const allLearned=()=>!!student&&student.studied.length===WORDS.length;
const memory=id=>student?.memory[id]||'new';
const weakIds=()=>WORDS.filter(d=>memory(d.id)==='review').map(d=>d.id);
const totalLearned=()=>student?.studied.length||0;
const currentWord=()=>group(ui.g)[ui.idx];
function shuffle(a){let b=[...a];for(let i=b.length-1;i>0;i--){let j=Math.floor(Math.random()*(i+1));[b[i],b[j]]=[b[j],b[i]]}return b}
function toast(message){let t=$('ntc-toast');t.textContent=message;t.hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.hidden=true,5000)}
function save(){if(student){student.ui={...ui};student.updatedAt=new Date().toISOString()}try{localStorage.setItem(STORE,JSON.stringify(store))}catch(e){storageOK=false;toast('浏览器无法保存学习进度，请允许保存本地数据。')}}
function createStudent(name,clas){return {name,clas,studied:[],memory:{},bookmark:{g:0,idx:0},ui:{page:0,g:0,idx:0,pinyin:false},flash:null,quiz:null,order:null,quizHistory:[],orderHistory:[],timeMs:0}}
function status(id){if(!hasLearned(id))return '<span class="ntc-state new">○ 未学习</span>';if(memory(id)==='review')return '<span class="ntc-state review">↻ 需要复习</span>';return '<span class="ntc-state">✓ 已学习</span>'}
function button(label,action,cls='',disabled=false){return `<button data-action="${action}" class="${cls}" ${disabled?'disabled':''}>${label}</button>`}
function go(page){stopAudio();ui.page=page;if(student&&allLearned()){if(page===2&&!student.flash)startFlash('all',false);if(page===3&&!student.quiz)startQuiz(false);if(page===4&&!student.order)startOrder(null,false)}save();render()}
function chooseGroup(g){stopAudio();ui.g=g;ui.idx=0;ui.page=1;save();render()}
function heading(title,subtitle='',tag=''){return `<div class="ntc-sectionhead"><div><h2>${title}</h2>${subtitle?`<p class="ntc-caption">${subtitle}</p>`:''}</div>${tag?`<span class="ntc-tag">${tag}</span>`:''}</div>`}
function meter(value,total){return `<div class="ntc-meter" role="progressbar" aria-label="进度" aria-valuenow="${value}" aria-valuemin="0" aria-valuemax="${total}"><span style="width:${total?value/total*100:0}%"></span></div>`}
function gate(){return `<div class="ntc-panel ntc-lock"><div class="ntc-kicker">先学习生词，再进行全课复习</div><h2>请先完成生词学习</h2><p>已学习 ${totalLearned()}/29 个词语。学完三组词语后，即可进行词汇卡片、综合练习和连词成句。</p>${meter(totalLearned(),29)}<div class="ntc-progressgroups">${[0,1,2].map(g=>`<button data-group="${g}">组别 ${g+1}<br>${learned(g)}/${group(g).length}个词语</button>`).join('')}</div>${button('继续学习 →','resume','ntc-primary')}</div>`}
function listView(){return `<div class="ntc-panel">${heading('词汇表','全课共29个词语，点击 ↗ 学习该词语',totalLearned()+'/29 已学习')}<div class="ntc-tablewrap"><table class="ntc-table"><thead><tr><th>汉字</th><th class="ntc-colpinyin">拼音</th><th class="ntc-coltype">词性</th><th>越南语释义</th><th>状态</th></tr></thead><tbody>${WORDS.map((d,i)=>`<tr><td class="ntc-hanzi">${d.w} <button class="ntc-play" data-word="${i}" aria-label="学习词语 ${d.w}">↗</button><button class="ntc-play" data-audio-word="${i}" aria-label="听词语 ${d.w}">◖</button></td><td class="ntc-colpinyin">${escapeHTML(d.p)}</td><td class="ntc-coltype">${escapeHTML(d.t)}</td><td>${escapeHTML(d.m)}</td><td>${status(i)}</td></tr>`).join('')}</tbody></table></div><div class="ntc-actions"><span class="ntc-caption">仅生词学习分为三组：10、10、9个词语。</span>${button('开始／继续学习 →','resume','ntc-primary')}</div></div>`}
function studyView(){let d=currentWord(),a=group(ui.g),isLast=d.id===28;return `<div class="ntc-panel">${heading('学习生词 · 组别 '+(ui.g+1),'学习词语、搭配与例句',`${ui.idx+1}/${a.length}`)}${meter(learned(ui.g),a.length)}<div class="ntc-study"><div class="ntc-wordbox"><div class="ntc-pinyin" style="visibility:${ui.pinyin?'visible':'hidden'}">${escapeHTML(d.p)}</div><div class="ntc-bigword ntc-writing" id="ntc-writing" aria-label="汉字笔顺">${d.w}</div><div class="ntc-meaning">${escapeHTML(d.m)}</div><span class="ntc-type">${escapeHTML(d.t)}</span><div class="ntc-smallbtns">${button('笔顺演示','strokes')}<button data-audio-word="${d.id}">◖ 听词语</button>${button(ui.pinyin?'隐藏拼音':'显示拼音','pinyin')}</div></div><div><div class="ntc-label">常用搭配</div><div class="ntc-cn">${escapeHTML(d.coll)}</div><hr><div class="ntc-label">例句</div><div class="ntc-cn">${escapeHTML(d.s)}</div><div class="ntc-smallbtns"><button data-audio-example="${d.id}">◖ 听例句</button></div><div class="ntc-note">${status(d.id)}</div></div></div><div class="ntc-actions">${button('← 上一个','prev-study','',d.id===0)}${button(isLast?'✓ 已学习 · 全课复习 →':ui.idx===a.length-1?'✓ 已学习 · 下一组 →':'✓ 已学习 · 下一个 →','mark-study','ntc-primary')}</div><div class="ntc-footnote">点击“已学习”记录学习进度。需要时，可点击“笔顺演示”查看汉字的书写顺序。</div></div>`}
function markStudy(){let d=currentWord();if(!student.studied.includes(d.id))student.studied.push(d.id);let next=WORDS.find(x=>!student.studied.includes(x.id));if(d.id<28){let id=d.id+1;ui.g=groupOf(id);ui.idx=id-ui.g*10;student.bookmark={g:ui.g,idx:ui.idx}}else if(!next){ui.page=2;student.bookmark={g:2,idx:8};if(!student.flash)startFlash('all',false)}else{ui.g=groupOf(next.id);ui.idx=next.id-ui.g*10;student.bookmark={g:ui.g,idx:ui.idx};toast('还有未学完的词语，请继续学习。')}save();render()}
function startFlash(filter='all',redraw=true){let ids=filter==='weak'?weakIds():WORDS.map(d=>d.id);if(!ids.length){toast('暂无需要复习的词语。');return}student.flash={filter,ids:shuffle(ids),at:0,flipped:false,ratings:{},done:false};save();if(redraw)render()}
function flashView(){let f=student.flash;if(f.done)f.done=false;let d=WORDS[f.ids[f.at]];return `<div class="ntc-panel">${heading('词汇卡片 · 全课复习',f.filter==='weak'?'复习练习中答错的词语':'全课29个词语随机排列，不分组',`${f.at+1}/${f.ids.length}`)}${meter(f.at+1,f.ids.length)}<div class="ntc-smallbtns" style="margin-bottom:16px">${button('重新打乱全课29个词语','flash-all')}${button('待复习词语 ('+weakIds().length+')','flash-weak','',!weakIds().length)}</div><div class="ntc-flash"><span class="ntc-label">${f.flipped?'背面':'正面'}</span>${f.flipped?`<span class="ntc-pinyin">${escapeHTML(d.p)}</span><span class="ntc-meaning">${escapeHTML(d.m)}</span><span class="ntc-type">${escapeHTML(d.t)}</span><small>${escapeHTML(d.coll)}</small><div class="ntc-note"><span class="ntc-cn">${escapeHTML(d.s)}</span><button class="ntc-play" data-audio-example="${d.id}" aria-label="听例句">◖</button></div>`:`<div style="display:flex;align-items:center;justify-content:center;gap:12px"><span class="ntc-bigword" style="font-size:clamp(40px,${d.w.length>2?'7':'10'}vw,${d.w.length>2?'80':'112'}px)">${d.w}</span><button class="ntc-play" data-audio-word="${d.id}" aria-label="听发音 ${d.w}" title="听发音">🔊</button></div>`}<div class="ntc-smallbtns">${button(f.flipped?'↶ 返回正面':'查看释义与例句 ↻','flip')}</div></div><div class="ntc-actions">${button('← 上一张','flash-prev','',f.at===0)}${f.at===f.ids.length-1?button('综合练习 →','quiz-page','ntc-primary'):button('下一张 →','flash-next','ntc-primary')}</div><div class="ntc-footnote">先看正面回忆词义；需要时翻到背面查看拼音、释义与例句。无需翻面即可切换卡片。</div></div>`}
const contextAlternatives={"0": [0, 1, 12], "1": [0, 1, 12], "2": [5, 10, 25], "3": [0, 1, 12], "4": [0, 1, 12], "5": [0, 6, 12], "6": [0, 1, 12], "7": [0, 1, 12], "8": [1, 11, 20], "9": [0, 1, 12], "10": [0, 1, 12], "11": [0, 6, 12], "12": [0, 1, 12], "13": [0, 1, 12], "14": [0, 1, 12], "15": [0, 1, 12], "16": [0, 1, 12], "17": [0, 1, 12], "18": [0, 1, 12], "19": [0, 1, 12], "20": [0, 1, 12], "21": [0, 1, 12], "22": [0, 1, 12], "23": [0, 1, 12], "24": [0, 1, 12], "25": [0, 1, 12], "26": [0, 1, 12], "27": [0, 1, 12], "28": [0, 1, 12]};
const CONFUSABLE={};
function makeQuestions(ids){let types=ids.map(id=>id%3===2?'context':id%3===0?'listen':'meaning');let positions=shuffle(ids.map((_,i)=>i%4));return shuffle(ids.map((id,i)=>{let alternatives=types[i]==='context'?contextAlternatives[id]:null;let opts=alternatives?shuffle(alternatives):shuffle(WORDS.filter(d=>d.id!==id&&!(CONFUSABLE[id]||[]).includes(d.id)).map(d=>d.id)).slice(0,3);opts.splice(positions[i],0,id);return {id,type:types[i],opts,correct:positions[i],picked:null}}))}
function startQuiz(redraw=true,ids=null){student.quiz={questions:makeQuestions(ids||WORDS.map(d=>d.id)),at:0,done:false,recorded:false};save();if(redraw)render()}
function quizView(){let q=student.quiz;if(q.done)return quizResults();let x=q.questions[q.at],d=WORDS[x.id],answered=x.picked!==null;return `<div class="ntc-panel">${heading('综合练习','听音选词 · 根据越南语释义选词 · 选词填空',`${q.at+1}/${q.questions.length}题`)}${meter(q.at,q.questions.length)}<div class="ntc-label">${x.type==='listen'?'听一听 · 听音选词':x.type==='meaning'?'认一认 · 根据越南语释义选词':'用一用 · 选词填空'}</div>${x.type==='listen'?`<button data-audio-word="${d.id}" class="ntc-primary">◖ 听词语</button><div class="ntc-footnote">如设备没有中文语音，可切换为根据越南语释义选词。</div>${button('切换为释义题','quiz-as-meaning','',answered)}`:x.type==='meaning'?`<div class="ntc-note">请根据越南语释义选择正确的汉语词语： <strong>${escapeHTML(d.m)}</strong></div>`:`<div class="ntc-cn">${escapeHTML(d.s.replace(d.w,'____'))}</div>`}<div class="ntc-quizopts">${x.opts.map((id,i)=>`<button data-answer="${i}" ${answered?'disabled':''} class="${answered?(i===x.correct?'ntc-correct':i===x.picked?'ntc-wrong':''):''}">${'ABCD'[i]}. ${WORDS[id].w}</button>`).join('')}</div>${answered?`<div class="ntc-note" role="status"><strong>${x.picked===x.correct?'✓ 正确':'✕ 不正确'}</strong><div class="ntc-cn">${d.w} · ${escapeHTML(d.p)}</div>${escapeHTML(d.m)}<br>${escapeHTML(d.s)}</div><div class="ntc-actions"><button data-audio-example="${d.id}">◖ 听例句</button>${button(q.at===q.questions.length-1?'查看结果 →':'下一题 →','quiz-next','ntc-primary')}</div>`:''}</div>`}
function pickQuiz(i){let q=student.quiz,x=q.questions[q.at];if(x.picked!==null)return;x.picked=i;if(i!==x.correct)student.memory[x.id]='review';save();render()}
function nextQuiz(){let q=student.quiz;if(q.questions[q.at].picked===null)return;if(q.at<q.questions.length-1)q.at++;else{q.done=true;if(!q.recorded){student.quizHistory.push({date:new Date().toISOString(),answers:q.questions.map(x=>({id:x.id,ok:x.picked===x.correct})),total:q.questions.length});q.recorded=true}}save();render()}
function quizResults(){let q=student.quiz,wrong=q.questions.filter(x=>x.picked!==x.correct),correct=q.questions.length-wrong.length;return `<div class="ntc-panel">${heading('综合练习结果','正确答案与待复习词语')}<div class="ntc-score">${correct}<small> / ${q.questions.length}题答对</small></div><div class="ntc-tag">${wrong.length}题答错</div>${wrong.map(x=>`<div class="ntc-miniresult"><strong>${WORDS[x.id].w}</strong> · ${escapeHTML(WORDS[x.id].p)}<br>你的选择： ${WORDS[x.opts[x.picked]].w}<br>正确释义： ${escapeHTML(WORDS[x.id].m)}<br>${escapeHTML(WORDS[x.id].s)}</div>`).join('')}<div class="ntc-actions">${button('重新练习全课词语','quiz-restart')}${button('重练错词','quiz-retry','',!wrong.length)}${button('连词成句 →','order-page','ntc-primary')}</div></div>`}
function startOrder(ids=null,redraw=true){let chosen=ids||WORDS.map(d=>d.id);student.order={ids:shuffle(chosen),at:0,bank:[],selected:[],checked:false,answers:[],done:false,recorded:false};newOrderQuestion();save();if(redraw)render()}
function newOrderQuestion(){let o=student.order;o.bank=shuffle(CHUNKS[o.ids[o.at]].map((_,i)=>i));if(o.bank.every((x,i)=>x===i))o.bank.reverse();o.selected=[];o.checked=false}
function orderView(){let o=student.order;if(o.done)return orderResults();let id=o.ids[o.at],d=WORDS[id],chunks=CHUNKS[id],ok=o.selected.every((x,i)=>x===i);return `<div class="ntc-panel">${heading('连词成句 · 全课复习','使用已学的29个例句，题目随机排列',`${o.at+1}/${o.ids.length}题`)}${meter(o.at,o.ids.length)}<div class="ntc-label">重点词语 · ${d.w}</div><p class="ntc-caption">按顺序选择词语，点击已选词语可将其放回。</p><div class="ntc-orderanswer ${o.checked?(ok?'ntc-correct':'ntc-wrong'):''}" aria-label="已排列的句子">${o.selected.length?o.selected.map((index,i)=>`<button data-remove="${i}" ${o.checked?'disabled':''}>${escapeHTML(chunks[index])}</button>`).join(''):'<span class="ntc-caption">请在这里排列句子……</span>'}</div><div class="ntc-chunks" aria-label="待选词语">${o.bank.map(index=>`<button class="${o.selected.includes(index)?'used':''}" data-chunk="${index}" ${o.checked||o.selected.includes(index)?'disabled':''}>${escapeHTML(chunks[index])}</button>`).join('')}</div><div class="ntc-actions"><div class="ntc-smallbtns">${button('↶ 撤销最后一项','order-undo','',!o.selected.length||o.checked)}${button('重新排列','order-clear','',!o.selected.length||o.checked)}</div>${button('检查答案','order-check','ntc-primary',o.selected.length!==chunks.length||o.checked)}</div>${o.checked?`<div class="ntc-note" role="status"><strong>${ok?'✓ 与例句顺序一致':'✕ 与例句顺序不一致'}</strong><div class="ntc-label">原例句</div><div class="ntc-cn">${escapeHTML(d.s)}</div><button data-audio-example="${id}">◖ 听例句</button></div><div class="ntc-actions"><span></span>${button(o.at===o.ids.length-1?'查看结果 →':'下一题 →','order-next','ntc-primary')}</div>`:''}<div class="ntc-footnote">本练习按原例句顺序评分，其他语序也可能符合语法。</div></div>`}
function addChunk(index){let o=student.order;if(o.checked||o.selected.includes(index))return;o.selected.push(index);save();render()}
function removeChunk(index){let o=student.order;if(o.checked)return;o.selected.splice(index,1);save();render()}
function checkOrder(){let o=student.order;if(o.checked||o.selected.length!==CHUNKS[o.ids[o.at]].length)return;o.checked=true;let id=o.ids[o.at],ok=o.selected.every((x,i)=>x===i);o.answers.push({id,ok});if(!ok)student.memory[id]='review';save();render()}
function nextOrder(){let o=student.order;if(!o.checked)return;if(o.at<o.ids.length-1){o.at++;newOrderQuestion()}else{o.done=true;if(!o.recorded){student.orderHistory.push({date:new Date().toISOString(),answers:o.answers.map(x=>({...x})),total:o.ids.length});o.recorded=true}}save();render()}
function orderResults(){let o=student.order,wrong=o.answers.filter(x=>!x.ok).map(x=>x.id),correct=o.answers.length-wrong.length;return `<div class="ntc-panel">${heading('连词成句结果','第31课综合复习')}<div class="ntc-score">${correct}<small> / ${o.answers.length}题答对</small></div><div class="ntc-tag">${wrong.length} 题需要重新练习</div>${wrong.map(id=>`<div class="ntc-miniresult"><strong>${WORDS[id].w}</strong><br><span class="ntc-cn">${escapeHTML(WORDS[id].s)}</span></div>`).join('')}<div class="ntc-actions">${button('重新练习全课句子','order-restart')}${button('重练错题','order-retry','',!wrong.length)}${button('查看学习统计 →','stats-page','ntc-primary')}</div></div>`}
function activityScore(kind,g){let history=kind==='quiz'?student.quizHistory:student.orderHistory,record=history[history.length-1],answers=record?.answers||[],ids=group(g).map(d=>d.id),inGroup=answers.filter(x=>ids.includes(x.id));let active=kind==='quiz'?student.quiz:student.order;if(active&&!active.done){let partial=kind==='quiz'?active.questions.filter(x=>x.picked!==null).map(x=>({id:x.id,ok:x.picked===x.correct})):active.answers;inGroup=partial.filter(x=>ids.includes(x.id));if(inGroup.length)return inGroup.filter(x=>x.ok).length+'/'+inGroup.length+' 进行中'}return inGroup.length?inGroup.filter(x=>x.ok).length+'/'+inGroup.length:'尚未练习'}
function statsView(){let weak=weakIds();return `<div class="ntc-panel">${heading('学习统计','当前浏览器中的第31课学习进度','第31课 · 29个词语')}<div class="ntc-statrow"><div class="ntc-stat"><label>已学词语</label><strong>${totalLearned()}<small> / 29</small></strong></div><div class="ntc-stat"><label>需要复习</label><strong>${weak.length}<small>个词语</small></strong></div></div><div class="ntc-tablewrap"><table class="ntc-table"><thead><tr><th>组别</th><th>已学习</th><th>待复习</th><th>综合练习</th><th>连词成句</th></tr></thead><tbody>${[0,1,2].map(g=>`<tr><td>组别 ${g+1}<div class="ntc-caption">${group(g).length}个词语</div></td><td>${learned(g)}/${group(g).length}</td><td>${group(g).filter(d=>memory(d.id)==='review').length}</td><td>${activityScore('quiz',g)}</td><td>${activityScore('order',g)}</td></tr>`).join('')}</tbody></table></div><div class="ntc-footnote">按词语所属组显示答对题数／已答题数。优先显示本轮进度，否则显示最近一轮结果。</div><hr><div class="ntc-sectionhead"><h2>待复习词语</h2>${button('用词汇卡片复习 →','flash-weak','',!weak.length||!allLearned())}</div><div class="ntc-terms">${weak.length?weak.map(id=>`<button data-word="${id}">${WORDS[id].w}</button>`).join(''):'<span class="ntc-caption">暂无需要复习的错词。</span>'}</div><div class="ntc-note">继续学习：组别 ${student.bookmark.g+1} · 词语 ${student.bookmark.idx+1}/${group(student.bookmark.g).length}.<br>本页累计学习时间约 ${Math.floor(student.timeMs/60000)} 分钟。已完成综合练习轮数： ${student.quizHistory.length}; 连词成句轮数： ${student.orderHistory.length}.</div><div class="ntc-actions">${button('继续学习','resume','ntc-primary')}${button('导出学习记录','backup')}${button('恢复学习记录','restore')}</div><div class="ntc-footnote">答错词语会列入待复习词语。浏览词汇卡片不等于掌握词语。</div></div>`}
function render(){clearWriting();let total=totalLearned();$('ntc-profile-button').textContent='HSK5 · 第31课';$('ntc-bookmark').textContent=student?total+'/29 个已学词语':'';$('ntc-tabs').innerHTML=pages.map((name,i)=>`<button class="ntc-tab ${ui.page===i?'active':''}" data-page="${i}" aria-pressed="${ui.page===i}">${i<5?i+1+'. ':''}${name}${i>=2&&i<=4&&!allLearned()?' 🔒':''}</button>`).join('');let showGroups=ui.page===1;$('ntc-groups').hidden=!showGroups;$('ntc-groups').innerHTML=showGroups?[0,1,2].map(g=>`<button data-group="${g}" class="${g===ui.g?'active':''}">组别 ${g+1} · ${group(g).length}个词语 · ${learned(g)}/${group(g).length}</button>`).join(''):'';$('ntc-sidegroups').innerHTML=showGroups?'<div class="ntc-navtitle">当前词汇组</div>'+[0,1,2].map(g=>`<button class="ntc-sidegroup ${g===ui.g?'active':''}" data-group="${g}"><span>组别 ${g+1}<br><small>词语 ${g*10+1}–${g*10+group(g).length}</small></span><small>${learned(g)}/${group(g).length}</small></button>`).join(''):'<div class="ntc-navtitle">第31课学习进度</div><div style="padding:0 10px">'+total+'/29 个已学词语'+meter(total,29)+'</div>';$('ntc-sidefoot').innerHTML='学完生词 →<br>全课综合复习。<br><br>进度保存在<br>当前浏览器中。';let html;if(ui.page>=2&&ui.page<=4&&!allLearned())html=gate();else html=[listView,studyView,flashView,quizView,orderView,statsView][ui.page]();$('ntc-view').innerHTML=html;if(ui.page===1)setupWriting();}
function stopAudio(){audioGeneration++;if(playback){playback.pause();playback=null}if('speechSynthesis' in window)window.speechSynthesis.cancel()}
const AUDIO_INDEX={"门槛":"data:audio/mpeg;base64,","这项工作的入职门槛并不高，但需要认真负责。":"data:audio/mpeg;base64,","报社":"data:audio/mpeg;base64,","大学毕业以后，她进入一家报社担任记者。":"data:audio/mpeg;base64,","编辑":"data:audio/mpeg;base64,","这位编辑正在认真检查准备发表的文章。":"data:audio/mpeg;base64,","嗯":"data:audio/mpeg;base64,","“嗯，我明白你的意思了，我们再商量一下。”":"data:audio/mpeg;base64,","轻易":"data:audio/mpeg;base64,","面对一次失败，我们不应该轻易放弃自己的目标。":"data:audio/mpeg;base64,","处理":"data:audio/mpeg;base64,","收到顾客的意见以后，经理立即安排人员处理这个问题。":"data:audio/mpeg;base64,","社区":"data:audio/mpeg;base64,","这个社区每个月都会组织适合老年人参加的活动。":"data:audio/mpeg;base64,","劝":"data:audio/mpeg;base64,","看到他连续工作了很久，同事们都劝他先休息一会儿。":"data:audio/mpeg;base64,","圆":"data:audio/mpeg;base64,","这张圆桌放在客厅中间，可以坐下六个人。":"data:audio/mpeg;base64,","标志":"data:audio/mpeg;base64,","开车经过学校附近时，司机应该特别注意路边的交通标志。":"data:audio/mpeg;base64,","出示":"data:audio/mpeg;base64,","进入展览馆以前，请向工作人员出示您的有效证件。":"data:audio/mpeg;base64,","赞成":"data:audio/mpeg;base64,","经过充分讨论，大多数居民都赞成这个计划。":"data:audio/mpeg;base64,","请愿书":"data:audio/mpeg;base64,","为了保护附近的公园，居民们共同提交了一份请愿书。":"data:audio/mpeg;base64,","恋爱":"data:audio/mpeg;base64,","他们在大学里认识，毕业以后才开始谈恋爱。":"data:audio/mpeg;base64,","迫切":"data:audio/mpeg;base64,","随着居民不断增加，这个社区迫切需要一所新的学校。":"data:audio/mpeg;base64,","犹豫":"data:audio/mpeg;base64,","面对这两个不同的选择，她犹豫了很久，还是没有作出决定。":"data:audio/mpeg;base64,","冷淡":"data:audio/mpeg;base64,","他对陌生人的态度有些冷淡，但对朋友十分热情。":"data:audio/mpeg;base64,","无所谓":"data:audio/mpeg;base64,","对我来说，坐在哪个位置都无所谓，只要能听清楚就行。":"data:audio/mpeg;base64,","值班":"data:audio/mpeg;base64,","为了保证游客的安全，工作人员会在节假日轮流值班。":"data:audio/mpeg;base64,","报告":"data:audio/mpeg;base64,","会议开始以前，她已经准备好了这份工作报告。":"data:audio/mpeg;base64,","八成":"data:audio/mpeg;base64,","他平时总是准时到，今天这么晚还没来，八成是路上堵车了。":"data:audio/mpeg;base64,","模糊":"data:audio/mpeg;base64,","时间过去太久，他对那件事的记忆已经有些模糊了。":"data:audio/mpeg;base64,","狡猾":"data:audio/mpeg;base64,","故事里的狐狸十分狡猾，总是想办法欺骗其他动物。":"data:audio/mpeg;base64,","了不起":"data:audio/mpeg;base64,","他靠自己的努力完成了这项艰巨的任务，真了不起。":"data:audio/mpeg;base64,","身段":"data:audio/mpeg;base64,","即使经验丰富，他也愿意放低身段，向年轻同事请教。":"data:audio/mpeg;base64,","缩短":"data:audio/mpeg;base64,","这条新公路大大缩短了两个城市之间的距离。":"data:audio/mpeg;base64,","看不起":"data:audio/mpeg;base64,","我们不应该因为一个人的工作普通，就看不起他。":"data:audio/mpeg;base64,","谦虚":"data:audio/mpeg;base64,","虽然取得了很好的成绩，她仍然保持谦虚好学的态度。":"data:audio/mpeg;base64,","实践":"data:audio/mpeg;base64,","学到了新的方法以后，我们还应该把它们付诸实践。":"data:audio/mpeg;base64,"};
function speak(text){stopAudio();const path=AUDIO_INDEX[text];if(!path){toast('未找到此内容的配套音频。');return}const generation=audioGeneration;const player=new Audio(path);playback=player;player.playbackRate=speed;player.onerror=()=>{if(generation===audioGeneration){$('ntc-voice-label').textContent='音频未加载';toast('无法加载音频，请确认 HTML 与 audio 文件夹一起保存或上传。')}};player.onended=()=>{if(playback===player)playback=null};player.play().then(()=>{if(generation!==audioGeneration){player.pause();return}$('ntc-voice-label').textContent='朗读：Xiaoxiao · 固定 MP3';}).catch(()=>{if(generation===audioGeneration)toast('音频暂时无法播放，请确认音频文件存在后再次点击。')})}
function backup(){const content=JSON.stringify({format:'ntc-hsk5-bai31-v3',profile:student},null,2);let url=URL.createObjectURL(new Blob([content],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='HSK5_Bai31_TienDo.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),2000)}
function restore(){let input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.addEventListener('change',async()=>{try{let v=JSON.parse(await input.files[0].text()),p=v.profile;if(v.format!=='ntc-hsk5-bai31-v3'||!p||typeof p.name!=='string'||typeof p.clas!=='string'||!Array.isArray(p.studied)||p.studied.some(id=>!Number.isInteger(id)||id<0||id>=29)||!p.memory)throw Error();if(!confirm('恢复第31课学习记录？当前记录将被替换。'))return;let id=store.active||'local';let clean=createStudent(p.name,p.clas);clean.studied=[...new Set(p.studied)];for(let k=0;k<29;k++)if(['remembered','review'].includes(p.memory[k]))clean.memory[k]=p.memory[k];if(p.bookmark&&Number.isInteger(p.bookmark.g)&&p.bookmark.g>=0&&p.bookmark.g<3&&Number.isInteger(p.bookmark.idx)&&p.bookmark.idx>=0&&p.bookmark.idx<group(p.bookmark.g).length)clean.bookmark=p.bookmark;for(let key of ['quizHistory','orderHistory'])if(Array.isArray(p[key]))clean[key]=p[key].filter(r=>r&&Array.isArray(r.answers)&&r.answers.every(a=>Number.isInteger(a.id)&&a.id>=0&&a.id<29&&typeof a.ok==='boolean'));clean.timeMs=Math.max(0,Number(p.timeMs)||0);store.profiles[id]=clean;store.active=id;student=clean;ui={page:5,g:0,idx:0,pinyin:false};save();render();toast('已恢复已学词语、复习状态与练习记录。')}catch(e){toast('无法读取有效的HSK5第31课学习记录。')}});input.click()}
root.addEventListener('click',event=>{let b=event.target.closest('button');if(!b||b.disabled)return;const data=b.dataset;if(data.audioWord!==undefined){speak(WORDS[+data.audioWord].w);return}if(data.audioExample!==undefined){speak(WORDS[+data.audioExample].s);return}if(data.page!==undefined){go(+data.page);return}if(data.group!==undefined){chooseGroup(+data.group);return}if(data.word!==undefined){let id=+data.word;ui.g=groupOf(id);ui.idx=id-ui.g*10;go(1);return}if(data.answer!==undefined){stopAudio();pickQuiz(+data.answer);return}if(data.chunk!==undefined){addChunk(+data.chunk);return}if(data.remove!==undefined){removeChunk(+data.remove);return}let a=data.action;if(!a)return;if(a==='stop'){stopAudio();return}switch(a){case'strokes':animateWriting();return;case'resume':ui.g=student.bookmark.g;ui.idx=student.bookmark.idx;go(1);return;case'pinyin':ui.pinyin=!ui.pinyin;break;case'prev-study':{let id=currentWord().id-1;ui.g=groupOf(id);ui.idx=id-ui.g*10;break}case'mark-study':stopAudio();markStudy();return;case'flip':student.flash.flipped=!student.flash.flipped;break;case'flash-all':if(!allLearned()){go(2);return}ui.page=2;startFlash('all');return;case'flash-weak':if(!allLearned()){go(2);return}ui.page=2;startFlash('weak');return;case'flash-prev':student.flash.at--;student.flash.flipped=false;break;case'flash-next':student.flash.at++;student.flash.flipped=false;break;case'quiz-page':go(3);return;case'order-page':go(4);return;case'stats-page':go(5);return;case'quiz-as-meaning':student.quiz.questions[student.quiz.at].type='meaning';break;case'quiz-next':stopAudio();nextQuiz();return;case'quiz-restart':startQuiz();return;case'quiz-retry':startQuiz(true,student.quiz.questions.filter(x=>x.picked!==x.correct).map(x=>x.id));return;case'order-undo':removeChunk(student.order.selected.length-1);return;case'order-clear':student.order.selected=[];break;case'order-check':checkOrder();return;case'order-next':stopAudio();nextOrder();return;case'order-restart':startOrder();return;case'order-retry':startOrder(student.order.answers.filter(x=>!x.ok).map(x=>x.id));return;case'backup':backup();return;case'restore':restore();return;default:return}save();render()});
root.addEventListener('change',event=>{if(event.target.id==='ntc-rate')speed=Number(event.target.value)});


let strokeWriters=[],strokeRun=0;
function clearWriting(){strokeRun++;for(const w of strokeWriters){w.pauseAnimation();}strokeWriters=[];}
function setupWriting(){const box=$('ntc-writing');if(!box)return;box.innerHTML='';for(const c of currentWord().w){const el=document.createElement('span');el.setAttribute('aria-label',c);box.appendChild(el);if(!STROKE_DATA[c]||typeof HanziWriter==='undefined'){el.textContent=c;if(!/[\u4e00-\u9fff]/.test(c)){el.style.width='24px';el.style.fontSize='30px';}continue;}strokeWriters.push(HanziWriter.create(el,c,{width:92,height:106,padding:3,strokeColor:'#a3455d',radicalColor:'#a3455d',outlineColor:'#ecd2db',strokeAnimationSpeed:0.7,delayBetweenStrokes:180,charDataLoader:()=>STROKE_DATA[c]}));}}
async function animateWriting(){const token=++strokeRun,list=[...strokeWriters];if(!list.length){toast('暂时无法显示笔顺。');return;}const button=root.querySelector('[data-action="strokes"]');if(button)button.disabled=true;try{for(const w of list)await w.hideCharacter({duration:0});for(const w of list){if(token!==strokeRun)return;await w.animateCharacter();}}finally{if(token===strokeRun&&button)button.disabled=false;}}

let lastTick=Date.now();setInterval(()=>{let now=Date.now();if(student&&!document.hidden){student.timeMs+=Math.min(now-lastTick,15000);save()}lastTick=now},15000);
window.addEventListener('pagehide',()=>{save();stopAudio()});
if(student&&ui.page>=2&&ui.page<=4&&allLearned()){if(ui.page===2&&!student.flash)startFlash('all',false);if(ui.page===3&&!student.quiz)startQuiz(false);if(ui.page===4&&!student.order)startOrder(null,false)}
save();render();if(!storageOK)toast('浏览器阻止保存数据，建议导出学习记录作为备份。');

